DELETE FROM odin_atlas_task_instance_lineage_adjacent
WHERE instance_guid IN

    #{instanceGuid}

   OR parent_instance_guid IN

    #{instanceGuid}

mapper.select:
SELECT COUNT(*)
FROM odin_atlas_task_instance_lineage_adjacent
WHERE instance_guid = #{instanceGuid}
  AND parent_instance_guid = #{parentInstanceGuid}

SELECT edge.`instance_guid` AS `instanceGuid`, edge.`parent_instance_guid` AS `dependentInstanceGuid` FROM `odin_atlas_task_instance_lineage_adjacent` AS edge JOIN `hydra_task_instances` AS parent_instance ON parent_instance.`guid` = edge.`parent_instance_guid` WHERE edge.`instance_guid` IN
#{instanceGuid}
AND ( parent_instance.`run_status` IS NULL OR parent_instance.`run_status` != #{finishedStatus} )
